options.customCss:
:root {
	--font-family: 'Open Sans', sans-serif;
	--font-weight-normal: 400;
	--font-weight-bold: 600;

	--font-size-body: 12px;
	--font-size-label: 14px;
	--font-size-test-notice: 12px;
	--font-size-input: 14px;
	--font-size-header: 22px;
	--font-size-paragraph: 14px;
	--font-size-link: 12px;
	--font-size-error: 12px;
	--font-size-html-h1: 28px;
	--font-size-html-h2: 20px;
	--font-size-html-h3: 16px;
	--font-size-html-h4: 14px;
	--font-size-html-h5: 12px;
	--font-size-html-h6: 10px;
	--font-size-subheader: 14px;

	/* ================================
	   BACKGROUND
	   ================================ */
	--color-background: #020b18;

	/* ================================
	   TEST NOTICE
	   ================================ */
	--color-test-notice-text: #38bdf8;
	--color-test-notice-bg: #06182b;
	--color-test-notice-border: #075985;

	/* ================================
	   CARD
	   ================================ */
	--color-card-bg: #061322;
	--color-card-border: #164e70;
	--color-card-shadow: rgba(0, 174, 255, 0.18);

	/* ================================
	   TEXT
	   ================================ */
	--color-link: #38bdf8;
	--color-header: #e0f2fe;
	--color-label: #bae6fd;
	--color-header-subtext: #7dd3fc;

	/* ================================
	   INPUTS
	   ================================ */

	/* IMPORTANT:
	   This controls the actual background
	   of Textarea, Text, Email, etc.
	*/
	--color-input-bg: #061322;

	--color-input-border: #155e75;
	--color-input-text: #f0f9ff;

	/* Neon cyan when clicked/focused */
	--color-focus-border: #00d9ff;

	/* ================================
	   SUBMIT BUTTON
	   ================================ */
	--color-submit-btn-bg: #008cff;
	--color-submit-btn-text: #ffffff;

	/* ================================
	   OTHER COLORS
	   ================================ */
	--color-error: #ff3b6b;
	--color-required: #00d9ff;
	--color-clear-button-bg: #075985;

	--color-html-text: #c7eaff;
	--color-html-link: #00d9ff;

	/* ================================
	   BORDER RADII
	   ================================ */
	--border-radius-card: 14px;
	--border-radius-input: 8px;
	--border-radius-clear-btn: 50%;
	--card-border-radius: 14px;

	/* ================================
	   SPACING
	   ================================ */
	--padding-container-top: 32px;
	--padding-card: 32px;

	--padding-test-notice-vertical: 14px;
	--padding-test-notice-horizontal: 24px;

	--margin-bottom-card: 20px;
	--padding-form-input: 14px;

	--card-padding: 32px;
	--card-margin-bottom: 20px;

	/* ================================
	   DIMENSIONS
	   ================================ */
	--container-width: 500px;
	--submit-btn-height: 52px;
	--checkbox-size: 18px;

	/* ================================
	   SHADOW
	   ================================ */
	--box-shadow-card:
		0px 0px 10px rgba(0, 174, 255, 0.15),
		0px 0px 30px rgba(0, 174, 255, 0.08);

	--opacity-placeholder: 0.55;
}


/* =========================================
   GLOBAL
   ========================================= */

*,
::after,
::before {
	box-sizing: border-box;
}


/* =========================================
   BODY
   ========================================= */

body {
	background-color: var(--color-background);
	padding-bottom: var(--padding-container-top);
}


/* =========================================
   FORM HEADER
   ========================================= */

.form-header h1 {
	color: var(--color-header);
	font-size: var(--font-size-header);
	font-weight: var(--font-weight-bold);
}

.form-header p {
	padding-top: 8px;
	color: var(--color-header-subtext);
	font-size: var(--font-size-paragraph);
	font-weight: 400;
}


/* =========================================
   LABELS
   ========================================= */

form label {
	display: block;
	text-align: left;
	font-size: var(--font-size-label);
	font-weight: 600;
	color: var(--color-label);
	padding-bottom: 6px;
}


/* =========================================
   TEXT INPUT + TEXTAREA
   ========================================= */

/* This is the important part */
form .form-input {
	border: 1px solid var(--color-input-border);
	border-radius: var(--border-radius-input);
	width: 100%;

	font-size: var(--font-size-input);
	color: var(--color-input-text);

	/* DARK BLUE BACKGROUND */
	background-color: var(--color-input-bg);

	font-weight: 400;
	padding: var(--padding-form-input);

	/* Neon-style transition */
	transition:
		border-color 0.2s ease,
		box-shadow 0.2s ease;
}


/* =========================================
   TEXTAREA
   ========================================= */

form textarea {
	max-width: 100%;
	min-height: 68px;
	resize: vertical;
}


/* =========================================
   INPUT FOCUS
   ========================================= */

form textarea:focus,
form input:focus {
	outline: none;

	border-color: var(--color-focus-border);

	box-shadow:
		0 0 0 1px var(--color-focus-border),
		0 0 12px rgba(0, 217, 255, 0.20);
}


/* =========================================
   PLACEHOLDER
   ========================================= */

::placeholder {
	color: #7dd3fc;
	opacity: var(--opacity-placeholder);
}


/* =========================================
   DROPDOWN
   ========================================= */

.select-input {
	border: 1px solid var(--color-input-border);
	border-radius: var(--border-radius-input);

	background-color: var(--color-input-bg);

	transition:
		border-color 0.2s ease,
		box-shadow 0.2s ease;
}

.select-input:focus-within {
	border: 1px solid var(--color-focus-border);

	box-shadow:
		0 0 0 1px var(--color-focus-border),
		0 0 12px rgba(0, 217, 255, 0.20);
}

form select {
	outline: transparent;
	border: none;
	border-radius: var(--border-radius-input);

	width: 100%;

	font-size: var(--font-size-input);
	color: var(--color-input-text);

	font-weight: 400;

	background-color: var(--color-input-bg);

	padding: var(--padding-form-input);

	border-right: 12px solid transparent;
}


/* =========================================
   DATE INPUT
   ========================================= */

input[type='date'] {
	font-family: var(--font-family);
}


/* =========================================
   SUBMIT BUTTON
   ========================================= */

#submit-btn {
	width: 100%;
	height: var(--submit-btn-height);

	padding: var(--padding-form-input);

	border-radius: var(--border-radius-input);
	border: 0;

	font-size: var(--font-size-input);
	font-weight: 600;
	font-family: var(--font-family);

	background-color: var(--color-submit-btn-bg);
	color: var(--color-submit-btn-text);

	cursor: pointer;

	box-shadow:
		0 0 10px rgba(0, 140, 255, 0.35),
		0 0 25px rgba(0, 140, 255, 0.15);

	transition:
		transform 0.2s ease,
		box-shadow 0.2s ease,
		opacity 0.2s ease;
}


/* Button hover */

#submit-btn:hover {
	opacity: 0.9;

	transform: translateY(-1px);

	box-shadow:
		0 0 15px rgba(0, 140, 255, 0.55),
		0 0 35px rgba(0, 140, 255, 0.25);
}


/* =========================================
   REQUIRED STAR
   ========================================= */

label.form-required::after {
	content: ' *';
	color: var(--color-required);
}


/* =========================================
   ERROR
   ========================================= */

.error-hidden {
	display: block;
	position: relative;

	color: var(--color-error);

	text-align: left;
	font-size: var(--font-size-error);
	font-weight: 400;

	visibility: hidden;

	padding-top: 6px;
	padding-bottom: 9px;
}

.error-show {
	visibility: visible;
}


/* =========================================
   HTML CONTENT
   ========================================= */

div.html {
	text-align: left;

	color: var(--color-html-text);

	font-size: var(--font-size-input);
}

div.html a {
	color: var(--color-html-link);
}


/* =========================================
   HORIZONTAL LINE
   ========================================= */

hr {
	border: 0;
	height: 1px;

	border-top: 1px solid var(--color-input-border);

	margin-top: 24px;
	margin-bottom: 24px;

	display: none;
}


/* =========================================
   FILE INPUT
   ========================================= */

.file-input-wrapper {
	position: relative;
	display: inline-block;
	width: 100%;
}


/* =========================================
   CLEAR BUTTON
   ========================================= */

.clear-button {
	position: absolute;

	right: 5px;
	top: 50%;

	transform: translateY(-65%);

	background-color: var(--color-clear-button-bg);

	border: none;
	border-radius: var(--border-radius-clear-btn);

	font-size: 14px;
	font-weight: 600;
	font-family: var(--font-family);

	color: white;

	width: 20px;
	height: 20px;

	text-align: center;
	line-height: 20px;

	cursor: pointer;
}


/* =========================================
   MOBILE
   ========================================= */

@media only screen and (max-width: 500px) {

	body {
		background-color: var(--color-background);
	}

	.container {
		width: 95%;
		min-height: 100vh;

		padding: 24px;

		border: 0;
		border-radius: 0;

		box-shadow: none;
	}

	.card {
		padding: 0;

		background-color: var(--color-card-bg);

		border: 0;
		border-radius: 0;

		box-shadow: none;

		margin-bottom: 0;
	}

	.form-header h1 {
		font-size: 20px;
	}

	form .form-input {
		background-color: var(--color-input-bg);
	}
}
